SELECT ?s ?p ?o WHERE {
  ?s rdf:type brick:Zone .
  FILTER(CONTAINS(STR(?s), "F3_Z01") || CONTAINS(STR(?s), "Core_mid") || CONTAINS(STR(?s), "core_mid"))
}

SELECT ?s ?p ?o WHERE {
  ?s ref:hasTimeseriesId .
  FILTER(CONTAINS(STR(?s), "F3_Z01") || CONTAINS(STR(?s), "Core_mid") || CONTAINS(STR(?s), "core_mid") || CONTAINS(STR(?s), "Zone_F3_Z01"))
}

SELECT ?s ?sclass WHERE {
  ?s rdf:type ?sclass .
  FILTER(CONTAINS(LCASE(STR(?s)), "f3_z01") || CONTAINS(LCASE(STR(?s)), "core_mid") || CONTAINS(LCASE(STR(?s)), "zone_f3"))
}

SELECT ?pt ?cls ?tsid WHERE {
  ?pt rdf:type ?cls .
  ?pt ref:hasTimeseriesId ?tsid .
  FILTER(?cls = brick:Zone_Air_Temperature_Sensor)
}

SELECT ?cls (COUNT(?p) AS ?n) WHERE {
  ?p rdf:type ?cls .
  ?p ref:hasTimeseriesId ?t .
} GROUP BY ?cls ORDER BY DESC(?n) LIMIT 40

